using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct FactionId : IEquatable<FactionId>, IComparable<FactionId>
    {
        public Guid Value { get; }

        public FactionId(Guid value)
        {
            Value = value;
        }

        public static FactionId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static FactionId NewRandom() => new FactionId(Guid.NewGuid());

        public static FactionId Parse(string text) => new FactionId(Guid.Parse(text));

        public static bool TryParse(string text, out FactionId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new FactionId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(FactionId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is FactionId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(FactionId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(FactionId left, FactionId right) => left.Equals(right);

        public static bool operator !=(FactionId left, FactionId right) => !left.Equals(right);
    }
}
